jsonTools.init:
function init(eli) {
  if (!eli.events) eli.events = { guard: function (fn) { return fn; }, safeAsync: function (p) { return p; } };

  // ─── Audience gate ────────────────────────────────────────────────
  // Hard-coded allowlist — match the tool_configs audienceEmails so the
  // tile is also hidden for everyone else, but defensive in case the
  // bundle ever ships broadly.
  var ALLOWED = {
    "andrew_nemiroff@colpal.com": 1,
    "jared_lerner@colpal.com": 1,
  };
  var ident = (eli.tools && typeof eli.tools.userIdentity === "function")
    ? eli.tools.userIdentity() : {};
  var userEmail = String((ident && ident.email) || "").toLowerCase().trim();
  if (!ALLOWED[userEmail]) {
    eli.log.event("tool", "bd_template_tester_skip", { reason: "not_allowed", email: userEmail });
    return;
  }

  // ─── IDB storage — multi-test ─────────────────────────────────────
  // Each test is a named snapshot sourced from a template (e.g. user
  // creates "NDA basic" off the NDA template, makes edits, saves it
  // and can reload it later). Tests live in the "config" store under
  // short keys:
  //
  //   key: "bdtt_index"           → { active: <id>, tests: [{...}] }
  //   key: "bdtt_test_<id>"       → { id, content, savedAt }
  //
  // The id is a sanitized version of the user-entered label (e.g.
  // "NDA basic" → "nda_basic"). Short on purpose — user explicitly
  // asked for no long file names.
  //
  // IMPORTANT: STORE_CONFIG uses keyPath "key" (NOT "id" — see kernel
  // initFeatureDB). Putting a value without a top-level `key` field
  // throws.
  var INDEX_KEY = "bdtt_index";
  // Per-test storage keys:
  //   bdtt_test_<id>     → temp-saved draft content (latest snapshot)
  //   bdtt_frozen_<id>   → frozen baseline (only for "from current doc"
  //                        tests — captures the original doc state so
  //                        Restore can return to it even after the user
  //                        has temp-saved over the working content).
  //                        Template-sourced tests skip this (Restore
  //                        re-fetches from bd_templates).
  // Special sourceTemplateId value used by the picker's "from current
  // document" option — distinguishes the current-doc flow from a real
  // template lookup.
  var CURRENT_DOC_SENTINEL = "__bdtt_current_doc__";
  function _testKey(id) { return "bdtt_test_" + id; }
  function _frozenKey(id) { return "bdtt_frozen_" + id; }
  function _saveFrozenBaseline(id, captured) {
    return eli.storage.put("config", {
      key: _frozenKey(id),
      id: id,
      content: JSON.stringify({
        savedDate: captured.savedDate,
        body: captured.body,
        sections: captured.sections,
      }),
      capturedAt: new Date().toISOString(),
    });
  }
  function _loadFrozenBaseline(id) {
    return eli.storage.get("config", _frozenKey(id)).catch(function () { return null; });
  }
  function _deleteFrozenBaseline(id) {
    return eli.storage.delete("config", _frozenKey(id)).catch(function () {});
  }

  function _slugifyId(label) {
    return String(label || "")
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, "_")
      .replace(/^_+|_+$/g, "")
      .slice(0, 40)              // hard cap so keys stay short
      || ("test_" + Date.now().toString(36).slice(-6));
  }

  function _loadIndex() {
    if (!eli.storage || typeof eli.storage.get !== "function") return Promise.resolve({ active: null, tests: [] });
    return eli.storage.get("config", INDEX_KEY).then(function (row) {
      if (!row) return { active: null, tests: [] };
      return { active: row.active || null, tests: Array.isArray(row.tests) ? row.tests : [] };
    }).catch(function () { return { active: null, tests: [] }; });
  }
  function _saveIndex(idx) {
    return eli.storage.put("config", {
      key: INDEX_KEY,
      active: idx.active || null,
      tests: idx.tests || [],
      updatedAt: new Date().toISOString(),
    });
  }
  // In-memory cache of the most-recently-loaded test content, keyed by
  // test id. Populated on Save and on Load. Lets a Reload-after-Reload
  // sequence skip the IDB get + JSON.parse — minor, but real on big
  // templates. Invalidated by close-overlay, by delete, and on any
  // explicit save (so it always reflects the latest persisted state).
  var _bdttContentMemCache = {};
  function _loadTestContent(id) {
    if (!id || !eli.storage || typeof eli.storage.get !== "function") return Promise.resolve(null);
    // Fast path — return a synthetic row from the in-memory cache.
    // Same shape _saveTestContent writes (key + content + savedAt),
    // so callers don't need to special-case the cached branch.
    var cached = _bdttContentMemCache[id];
    if (cached) {
      return Promise.resolve({
        key: _testKey(id),
        id: id,
        content: cached._serialized || JSON.stringify({
          savedDate: cached.savedDate,
          body: cached.body,
          sections: cached.sections,
        }),
        savedAt: cached._savedAt || null,
      });
    }
    return eli.storage.get("config", _testKey(id)).then(function (row) {
      if (row && row.content) {
        // Warm cache from the IDB hit so the NEXT Reload is hot.
        try {
          var parsed = JSON.parse(row.content);
          parsed._serialized = row.content;
          parsed._savedAt = row.savedAt;
          _bdttContentMemCache[id] = parsed;
        } catch (_) { /* tolerate — cache miss next time */ }
      }
      return row;
    }).catch(function () { return null; });
  }
  function _saveTestContent(id, captured) {
    if (!eli.storage || typeof eli.storage.put !== "function") {
      return Promise.reject(new Error("eli.storage unavailable"));
    }
    var serialized = JSON.stringify({
      savedDate: captured.savedDate,
      body: captured.body,
      sections: captured.sections,
    });
    var savedAt = new Date().toISOString();
    // Warm the memory cache up-front — same content we're about to
    // persist, so the next _loadTestContent skips IDB + parse.
    _bdttContentMemCache[id] = {
      savedDate: captured.savedDate,
      body: captured.body,
      sections: captured.sections,
      _serialized: serialized,
      _savedAt: savedAt,
    };
    return eli.storage.put("config", {
      key: _testKey(id),
      id: id,
      content: serialized,
      savedAt: savedAt,
    });
  }
  // Wipes the per-test content row AND any frozen-baseline row from
  // IDB. Returns a promise that resolves to true on success, false on
  // failure. Logs the failure (previously this swallowed errors
  // silently, hiding the case where delete didn't actually remove the
  // row — user-reported regression).
  function _deleteTest(id) {
    if (!id) return Promise.resolve(true);
    var key = _testKey(id);
    // Drop the in-memory cache for this id so a recreate with the
    // same id doesn't see stale content.
    delete _bdttContentMemCache[id];
    var ops = [
      eli.storage.delete("config", key),
      // Frozen baseline is only present for current-doc tests, but
      // calling delete on a missing key is a harmless no-op.
      eli.storage.delete("config", _frozenKey(id)).catch(function () {}),
    ];
    return Promise.all(ops)
      .then(function () {
        return eli.storage.get("config", key).then(function (row) {
          if (row) {
            eli.log.event("tool", "bd_template_tester_delete_residue", { key: key });
            return false;
          }
          return true;
        });
      })
      .catch(function (err) {
        eli.log.event("tool", "bd_template_tester_delete_failed", { key: key, msg: err && err.message });
        return false;
      });
  }

  // ─── Word-doc capture/load ────────────────────────────────────────
  // Mirrors build_draft's _captureActiveDocAsTemplate + _loadTemplateToWord.
  // We can't directly reuse them (build_draft is its own bundle and those
  // helpers aren't on window), so we duplicate the minimal capture+load
  // logic here. Body OOXML + per-section H/F captures = full template
  // fidelity.
  function _captureActiveDoc() {
    return eli.host.runRaw("bd_template_tester:capture_body", function (context) {
      var doc = context.document;
      var bodyOoxml = doc.body.getOoxml();
      var sections = doc.sections;
      sections.load("items");
      return context.sync().then(function () {
        return { body: bodyOoxml.value, sectionCount: sections.items.length };
      });
    }).then(function (state) {
      var sectionsData = [];
      var chain = Promise.resolve();
      for (var i = 0; i < state.sectionCount; i++) {
        (function (idx) {
          chain = chain.then(function () {
            return eli.host.runRaw("bd_template_tester:capture_section_" + idx, function (context) {
              var sections = context.document.sections;
              sections.load("items");
              return context.sync().then(function () {
                if (idx >= sections.items.length) return null;
                var sec = sections.items[idx];
                var grabs = {
                  primaryH: sec.getHeader("Primary").getOoxml(),
                  firstPageH: sec.getHeader("FirstPage").getOoxml(),
                  evenPagesH: sec.getHeader("EvenPages").getOoxml(),
                  primaryF: sec.getFooter("Primary").getOoxml(),
                  firstPageF: sec.getFooter("FirstPage").getOoxml(),
                  evenPagesF: sec.getFooter("EvenPages").getOoxml(),
                };
                return context.sync().then(function () {
                  return {
                    index: idx,
                    headers: {
                      primary: grabs.primaryH.value || "",
                      firstPage: grabs.firstPageH.value || "",
                      evenPages: grabs.evenPagesH.value || "",
                    },
                    footers: {
                      primary: grabs.primaryF.value || "",
                      firstPage: grabs.firstPageF.value || "",
                      evenPages: grabs.evenPagesF.value || "",
                    },
                  };
                });
              });
            }).then(function (data) { if (data) sectionsData.push(data); });
          });
        })(i);
      }
      return chain.then(function () {
        return { body: state.body, sections: sectionsData, savedDate: new Date().toISOString() };
      });
    });
  }

  // Load a template (JSON content string) into the active doc. Mirrors
  // build_draft's _loadTemplateToWord — body OOXML insert + per-section
  // header/footer inserts + font normalization.
  function _loadDocFromContent(contentString) {
    var parsed = null;
    try { parsed = JSON.parse(contentString); } catch (e) {
      return Promise.reject(new Error("Invalid template content (not JSON)"));
    }
    if (!parsed || !parsed.body) {
      return Promise.reject(new Error("Template has no body OOXML"));
    }
    return eli.host.runRaw("bd_template_tester:load_body", function (context) {
      var body = context.document.body;
      body.insertOoxml(parsed.body, Word.InsertLocation.replace);
      body.font.name = "Times New Roman";
      body.font.size = 11;
      var tables = body.tables;
      tables.load("items");
      var sections = context.document.sections;
      sections.load("items");
      return context.sync().then(function () {
        for (var ti = 0; ti < tables.items.length; ti++) {
          tables.items[ti].getRange().font.name = "Times New Roman";
        }
        return context.sync().then(function () { return sections.items.length; });
      });
    }).then(function (sectionCount) {
      if (!parsed.sections || !parsed.sections.length) return null;
      var chain = Promise.resolve();
      parsed.sections.forEach(function (secData, idx) {
        chain = chain.then(function () {
          return eli.host.runRaw("bd_template_tester:load_section_" + idx, function (context) {
            var sections = context.document.sections;
            sections.load("items");
            return context.sync().then(function () {
              if (idx >= sections.items.length) return;
              var sec = sections.items[idx];
              var hdrs = secData.headers || {};
              var ftrs = secData.footers || {};
              if (hdrs.primary) sec.getHeader("Primary").insertOoxml(hdrs.primary, Word.InsertLocation.replace);
              if (hdrs.firstPage) sec.getHeader("FirstPage").insertOoxml(hdrs.firstPage, Word.InsertLocation.replace);
              if (hdrs.evenPages) sec.getHeader("EvenPages").insertOoxml(hdrs.evenPages, Word.InsertLocation.replace);
              if (ftrs.primary) sec.getFooter("Primary").insertOoxml(ftrs.primary, Word.InsertLocation.replace);
              if (ftrs.firstPage) sec.getFooter("FirstPage").insertOoxml(ftrs.firstPage, Word.InsertLocation.replace);
              if (ftrs.evenPages) sec.getFooter("EvenPages").insertOoxml(ftrs.evenPages, Word.InsertLocation.replace);
              return context.sync();
            });
          });
        });
      });
      return chain;
    });
  }

  // ─── Overlay state ────────────────────────────────────────────────
  // saveState: "saved" | "unsaved" — reflects whether the in-doc state
  // matches the persisted content for the ACTIVE test. Resets to
  // "unsaved" after Reload (user must save again if they want the
  // next reload to include subsequent edits) and on Switch Test.
  var saveState = "unsaved";
  var _bdttIndex = null;       // cached {active, tests}; refreshed per open
  var _bdttTemplates = null;   // cached bd_templates rows; refreshed per open
  // Advanced section open/closed — Restore + Overwrite both live in
  // the same accordion, defaulting to closed. Session-local; resets
  // to false when the overlay re-opens.
  var _bdttAdvancedOpen = false;
  // The switcher row (dropdown + New + 🗑) is now collapsed BY DEFAULT
  // on every overlay open — the active test name shows as a plain
  // heading with a chevron the user can click to expand. Reduces
  // visual noise when the user just wants to Temp Save / Reload on
  // the current test. Click the chevron to reveal the full chrome.
  // Stays collapsed across re-renders within a session; resets on
  // overlay close (default = collapsed again on reopen).
  var _bdttHeaderCollapsed = true;
  // Tracks Build Draft Step 1's render lifecycle. Three states:
  //   • _bdttStep1State === "rendering": Step 1 is mid-substitution
  //     (between step1_start and step1_done). Banner shows a pulsing
  //     "Rendering…" indicator so the user knows the doc is in a
  //     transient state and not to interact with it yet.
  //   • _bdttStep1State === "done": Step 1 completed. Banner shows
  //     the post-generation snapshot CTA.
  //   • _bdttStep1State === null: no Step 1 activity this session.
  // _bdttLastStep1 captures the latest ts + fieldCount payload from
  // whichever event most recently fired.
  var _bdttStep1State = null;
  var _bdttLastStep1 = null;  // { ts, fieldCount } | null

  // ─── Overlay DOM (one in flight at a time) ────────────────────────
  function _openOverlay() {
    _closeOverlay();
    var ov = document.createElement("div");
    ov.id = "_bdtt_overlay";
    ov.style.cssText = [
      "position:fixed",
      "top:80px",
      "right:24px",
      "width:360px",
      "max-height:80vh",
      "z-index:99998",
      "background:#fff",
      "border:1px solid #cbd5e1",
      "box-shadow:0 12px 36px rgba(15,23,42,0.28)",
      "font-family:Inter,'Segoe UI',system-ui,sans-serif",
      "display:flex",
      "flex-direction:column",
      "overflow:hidden",
    ].join(";") + ";";
    ov.innerHTML =
      '<div id="_bdtt_header" style="padding:11px 14px;background:linear-gradient(135deg,#1e3a8a,#1565c0);color:#fff;display:flex;align-items:center;justify-content:space-between;gap:8px;cursor:move;user-select:none;">' +
        '<div style="display:flex;align-items:center;gap:8px;min-width:0;flex:1;">' +
          '<span style="font-size:14px;line-height:1;">🧪</span>' +
          '<span style="font-size:13px;font-weight:800;letter-spacing:0.02em;white-space:nowrap;">Template Tester</span>' +
        '</div>' +
        '<button id="_bdtt_close" type="button" style="background:rgba(255,255,255,0.18);border:1px solid rgba(255,255,255,0.4);color:#fff;padding:3px 9px;font-size:10px;font-weight:700;cursor:pointer;border-radius:0;line-height:1.2;">✕</button>' +
      '</div>' +
      // Tab strip — sticky between header and scrollable content.
      '<div id="_bdtt_tabs" style="display:flex;border-bottom:1px solid #cbd5e1;background:#f8fafc;flex:0 0 auto;"></div>' +
      // Tab content area — scrollable, paddings live here so the tab
      // bar above stays flush with the chrome.
      '<div id="_bdtt_body" style="padding:14px;display:flex;flex-direction:column;gap:10px;overflow-y:auto;flex:1 1 auto;"></div>';
    document.body.appendChild(ov);

    var headerEl = document.getElementById("_bdtt_header");
    if (typeof window._eliMakeDraggable === "function" && headerEl) {
      try { window._eliMakeDraggable(ov, headerEl); } catch (_) {}
    }
    // Bottom-right resize grip (kernel helper). Appends a ._eli3_dialog_resize_grip
    // div positioned absolute, mousedown-driven width/height drag with
    // 320×240 min, viewport−20 max. Our overlay's flex-column layout
    // means the scrollable tab body expands to fill the new height
    // automatically — no per-tab adjustments needed.
    if (typeof window._eliMakeResizable === "function") {
      try { window._eliMakeResizable(ov); } catch (_) {}
    }
    document.getElementById("_bdtt_close").onclick = _closeOverlay;

    // Paint tabs + initial body
    _renderTabs();
    _renderOverlayBody();
  }

  // Tab bar — two tabs: Test (current functionality) and Scan (new,
  // shows {{DEF}} tags found in the active doc with copy helpers).
  // Active tab tracked in _bdttTab (in-memory only; resets to "test"
  // on each fresh overlay open).
  var _bdttTab = "test";
  function _renderTabs() {
    var tabs = document.getElementById("_bdtt_tabs");
    if (!tabs) return;
    var defs = [
      { id: "test", label: "Test" },
      { id: "scan", label: "Scan" },
    ];
    tabs.innerHTML = defs.map(function (t) {
      var active = (t.id === _bdttTab);
      var style = [
        "flex:1",
        "padding:9px 10px",
        "font-size:11px",
        "font-weight:800",
        "letter-spacing:0.08em",
        "text-transform:uppercase",
        "background:" + (active ? "#fff" : "transparent"),
        "color:" + (active ? "#0f172a" : "#64748b"),
        "border:none",
        "border-bottom:" + (active ? "2px solid #1565c0" : "2px solid transparent"),
        "cursor:pointer",
        "font-family:inherit",
      ].join(";");
      return '<button type="button" data-bdtt-tab="' + t.id + '" style="' + style + '">' + _esc(t.label) + '</button>';
    }).join("");
    tabs.querySelectorAll("[data-bdtt-tab]").forEach(function (btn) {
      btn.onclick = function () {
        var id = btn.getAttribute("data-bdtt-tab");
        if (id === _bdttTab) return;
        _bdttTab = id;
        _renderTabs();
        _renderOverlayBody();
      };
    });
  }
  function _closeOverlay() {
    var existing = document.getElementById("_bdtt_overlay");
    if (existing && existing.parentNode) existing.parentNode.removeChild(existing);
    // Clear cached scan results so reopening the overlay re-scans
    // against the current doc — stale defs after an edit would be
    // worse than just running the scan again.
    _bdttScanDefs = null;
    _bdttScanReport = null;
    // Drop per-card pill selections too — defaults to first/second
    // option on next open is the expected fresh-start behavior.
    _bdttCardSelections = {};
    // Clear the Scan tab's live filter so a fresh open shows all rows.
    _bdttScanFilter = "";
    // Drop the Step-1 banner state — a "step 1 just ran" notification
    // that's an hour old by the next open isn't useful.
    _bdttLastStep1 = null;
    _bdttStep1State = null;
    // Keep the content cache across overlay-close/open cycles —
    // reopening within a few seconds is a common pattern (auto-open
    // does it on every page load) and the cache speeds Reload there.
    // We do NOT clear _bdttContentMemCache here.
    // Reset to Test tab so reopen starts in the primary workflow,
    // and re-collapse the Template Tools accordion. Also un-collapse
    // the active-view header so the next overlay open shows the
    // switcher / + New / 🗑 controls again.
    _bdttTab = "test";
    _bdttAdvancedOpen = false;
    // Default-collapsed: reopening the overlay always lands on the
    // compact "🧪 NDA basic · Source: …" header. User clicks the
    // chevron to reveal the switcher if they want to switch tests.
    _bdttHeaderCollapsed = true;
  }

  // Render the body of an already-mounted overlay. Pulled out so the
  // "switch test", "create new test", "delete test" actions can re-paint
  // without rebuilding the chrome (header + draggable wiring).
  //
  // Also enumerates which tests have saved content (one config-store
  // scan, then cached on _bdttSavedSet) so both views can mark
  // resumable tests with a 💾 indicator without N extra IDB reads.
  var _bdttSavedSet = null;
  function _renderOverlayBody() {
    var body = document.getElementById("_bdtt_body");
    if (!body) return;
    if (_bdttTab === "scan") { _renderScanTab(body); return; }
    Promise.all([_loadIndex(), _loadTemplates(), _loadSavedSet()]).then(function (results) {
      _bdttIndex = results[0];
      _bdttTemplates = results[1];
      _bdttSavedSet = results[2];
      // Clean up any orphan content rows (failed delete residue, stale
      // pre-refactor rows) using the freshly-loaded index. Background
      // — doesn't block the render.
      _sweepOrphans(_bdttIndex, _bdttSavedSet);
      if (!_bdttIndex.tests.length || !_bdttIndex.active) {
        // First-time / no-active state: ask user to create their first test.
        _renderPicker(body);
      } else {
        _renderActive(body);
      }
    }).catch(function (err) {
      body.innerHTML = '<div style="color:#b91c1c;font-size:12px;">Failed to load: ' + _esc(err && err.message || "unknown") + '</div>';
    });
  }
  function _loadSavedSet() {
    if (!eli.storage || typeof eli.storage.getAll !== "function") return Promise.resolve({});
    return eli.storage.getAll("config").then(function (rows) {
      var set = {};
      (rows || []).forEach(function (r) {
        if (!r || !r.key) return;
        if (String(r.key).indexOf("bdtt_test_") !== 0) return;
        if (!r.content) return;
        set[r.key.slice("bdtt_test_".length)] = true;
      });
      return set;
    }).catch(function () { return {}; });
  }

  // Opportunistic orphan sweep: every bdtt_test_<id> IDB row whose
  // <id> isn't in the current index is residue from a previous failed
  // delete (or stale data from before the multi-test refactor).
  // Called from _renderOverlayBody AFTER both index and saved-set are
  // freshly loaded — running it inside _loadSavedSet races with the
  // parallel _loadIndex and could nuke a just-created test.
  function _sweepOrphans(idx, savedSet) {
    if (!idx || !Array.isArray(idx.tests)) return;
    var knownIds = {};
    idx.tests.forEach(function (t) { if (t && t.id) knownIds[t.id] = true; });
    Object.keys(savedSet || {}).forEach(function (id) {
      if (!knownIds[id]) {
        eli.storage.delete("config", "bdtt_test_" + id).catch(function () {});
        delete savedSet[id];
        eli.log.event("tool", "bd_template_tester_orphan_swept", { id: id });
      }
    });
    // Also sweep stale frozen-baseline rows the same way. These are
    // separate IDB keys (bdtt_frozen_<id>) so they don't show up in
    // savedSet — scan the config store directly.
    eli.storage.getAll("config").then(function (rows) {
      (rows || []).forEach(function (r) {
        if (!r || !r.key) return;
        var k = String(r.key);
        if (k.indexOf("bdtt_frozen_") !== 0) return;
        var orphanId = k.slice("bdtt_frozen_".length);
        if (!knownIds[orphanId]) {
          eli.storage.delete("config", k).catch(function () {});
          eli.log.event("tool", "bd_template_tester_frozen_orphan_swept", { id: orphanId });
        }
      });
    }).catch(function () { /* tolerate */ });
  }
  function _testHasSaved(id) {
    return !!(_bdttSavedSet && _bdttSavedSet[id]);
  }

  function _renderPicker(body) {
    var hasTests = !!(_bdttIndex.tests && _bdttIndex.tests.length);
    // The picker is now the explicit "what do you want to do" hub.
    // Two sections: existing tests (with smart Open = switch ± reload)
    // on top, create-new below. When there are no tests, only the
    // create section renders.
    var existingHtml = hasTests
      ? '<div style="display:flex;flex-direction:column;gap:6px;border:1px solid #cbd5e1;background:#f8fafc;padding:10px 12px;">' +
          '<div style="font-size:10px;font-weight:900;color:#0f172a;letter-spacing:0.1em;text-transform:uppercase;">🔄 Existing Tests</div>' +
          '<div style="font-size:10px;color:#64748b;line-height:1.4;">' +
            'Picking a test with <strong>💾</strong> reloads its saved draft into the doc and opens Step 1. ' +
            'Tests with no save just switch active.' +
          '</div>' +
