  // Word.runs per Create (N = section count) which is meaningful on
  // multi-section templates.
  function _createTestFromTemplate(id, label, sourceTemplateId) {
    if (!_acquireBusy("Create Test")) return;
    var tpl = (_bdttTemplates || []).find(function (r) { return r.id === sourceTemplateId; });
    var entry = {
      id: id,
      label: label,
      sourceMode: "template",
      sourceTemplateId: sourceTemplateId,
