      nestedIf:       (l.nestedIf       || []).filter(function (it) { return _has(it.raw); }),
      emptyDef:       (l.emptyDef       || []).filter(function (it) { return _has(it.raw) || _has(it.name); }),
      unmatchedIf:    (l.unmatchedIf    || []).filter(function (it) { return _has(it.raw); }),
      unmatchedEndif: (l.unmatchedEndif || []).filter(function (it) { return _has(it.raw); }),
