  }

  function _paintScanResults(report) {
    var resEl = document.getElementById("_bdtt_scan_results");
    if (!resEl) return;
    if (Array.isArray(report)) report = { counts: null, defs: report, orphans: [], lint: null };
    // Apply the filter — counts at the TOP stay unfiltered (they're a
    // health summary of the whole doc, not the visible-rows list). Defs
    // and orphans and lint use the filtered slice.
    var unfilteredDefCount = (report.defs || []).length;
    var unfilteredOrphanCount = (report.orphans || []).length;
    var filtered = _filterReport(report, _bdttScanFilter);
    var counts = report.counts || {};
    var defs = filtered.defs || [];
    var orphans = filtered.orphans || [];
    var lint = filtered.lint || { singleEquals: [], missingColon: [], nestedIf: [], emptyDef: [], unmatchedIf: [], unmatchedEndif: [] };
    var totalTags = (counts.IF || 0) + (counts.ELSEIF || 0) + (counts.ELSE || 0) +
                    (counts.ENDIF || 0) + (counts.DEF || 0) + (counts.TITLE || 0) +
                    (counts.DELETE_LINE || 0) + (counts.ENTER || 0) + (counts.key || 0);
    if (!totalTags) {
      resEl.innerHTML =
        '<div style="font-size:11px;color:#64748b;padding:8px 10px;border:1px dashed #cbd5e1;background:#f8fafc;text-align:center;margin-top:6px;">' +
          'No <code style="font-family:monospace;">{{...}}</code> tags found in this document.' +
