    // Filter input — sticky-feeling between health summary and the rest.
    // Only renders when there are enough DEFs to make filtering useful
    // (saves vertical space on tiny templates).
    var filterHtml = '';
    if (unfilteredDefCount + unfilteredOrphanCount >= 4 || _bdttScanFilter) {
      var hiddenDefCount = unfilteredDefCount - defs.length;
      var hiddenLabel = '';
      if (_bdttScanFilter) {
        hiddenLabel = '<div style="font-size:9px;color:#64748b;letter-spacing:0.04em;">' +
          'Showing <strong style="color:#0f172a;">' + defs.length + '</strong> of ' + unfilteredDefCount + ' DEF' + (unfilteredDefCount === 1 ? '' : 's') +
          (hiddenDefCount ? ' · ' + hiddenDefCount + ' hidden' : '') +
        '</div>';
