        '<div style="display:flex;flex-direction:column;gap:4px;margin:6px 0 2px;">' +
          '<div style="display:flex;gap:4px;align-items:stretch;">' +
            '<input id="_bdtt_scan_filter" type="text" placeholder="Filter — name, option, or tag text…" value="' + _esc(_bdttScanFilter) + '" style="flex:1;padding:6px 8px;font-size:11px;font-family:inherit;border:1px solid #cbd5e1;border-radius:0;background:#fff;" />' +
            (_bdttScanFilter
              ? '<button id="_bdtt_scan_filter_clear" type="button" title="Clear filter" style="padding:0 10px;font-size:11px;font-weight:700;background:#fef2f2;border:1px solid #fca5a5;color:#991b1b;cursor:pointer;border-radius:0;line-height:1;">✕</button>'
              : '') +
          '</div>' +
          hiddenLabel +
        '</div>';
