    // Wire pill picks + copy buttons + jump-to-doc buttons via event
    // delegation on the results container. One listener handles all.
    resEl.onclick = function (e) {
      // Jump-to-doc click — find this tag in the body and select it.
      // Handle BEFORE pill/copy so 🔎 buttons placed inside cards work.
      var jumpBtn = e.target.closest && e.target.closest("[data-bdtt-jump]");
      if (jumpBtn) {
        e.stopPropagation();
        _onFindInDoc(jumpBtn.getAttribute("data-bdtt-jump"));
        return;
      }
      // Pill click — update per-card selection, re-render that card.
      var pill = e.target.closest && e.target.closest("[data-bdtt-pick]");
      if (pill) {
        var pName = pill.getAttribute("data-bdtt-name");
        var role  = pill.getAttribute("data-bdtt-pick");
        var idx   = parseInt(pill.getAttribute("data-bdtt-idx"), 10);
        var def = (_bdttScanDefs || []).find(function (d) { return d.name === pName; });
        if (!def) return;
        var sel = _getCardSel(def);
        if (role === "if") sel.ifIdx = idx;
        else if (role === "elseif") sel.elseifIdx = idx;
        // Repaint only this card in place — cheaper than full re-render
        // and keeps scroll position stable.
        var cardEl = pill.closest("[data-bdtt-card]");
        if (cardEl) {
          var hintWasVisible = false;
          var hint = cardEl.querySelector("[data-bdtt-endif-hint]");
          if (hint) hintWasVisible = (hint.style.display !== "none");
          var temp = document.createElement("div");
          temp.innerHTML = _renderDefCard(def);
          var fresh = temp.firstElementChild;
          if (fresh && cardEl.parentNode) {
            cardEl.parentNode.replaceChild(fresh, cardEl);
            // Preserve the ENDIF reminder if it was already shown — the
            // user already saw it once; flipping a pill shouldn't make
            // it disappear.
            if (hintWasVisible) {
              var newHint = fresh.querySelector("[data-bdtt-endif-hint]");
              if (newHint) newHint.style.display = "block";
            }
          }
        }
        return;
      }
      // Copy-button click — same as before.
      var btn = e.target.closest && e.target.closest("[data-bdtt-copy]");
      if (!btn) return;
      var name = btn.getAttribute("data-bdtt-name");
      var kind = btn.getAttribute("data-bdtt-copy");
      var def2 = (_bdttScanDefs || []).find(function (d) { return d.name === name; });
      if (!def2) return;
      var snippet = _renderCopyText(def2, kind);
      if (!snippet) return;
      _copyText(snippet, kind, name);
      if (kind === "if" || kind === "elseif") {
        var card = btn.closest && btn.closest("[data-bdtt-card]");
        var hint2 = card && card.querySelector("[data-bdtt-endif-hint]");
        if (hint2) hint2.style.display = "block";
      }
    };
  }

  // Health summary — IF/ENDIF balance is the critical check (engine
  // misparses an unbalanced template and silently drops branches).
  // ELSE counts are informational, not health-critical, because ELSE
  // without an IF is harmless (just text in the doc).
  function _renderHealthSummary(counts, defCount, orphanCount, lint) {
    var ifN     = counts.IF     || 0;
    var elseifN = counts.ELSEIF || 0;
    var elseN   = counts.ELSE   || 0;
    var endifN  = counts.ENDIF  || 0;
    var titleN  = counts.TITLE  || 0;
    var keyN    = counts.key    || 0;
    // Stack-walked balance is the source of truth — pairs IFs to
    // their ENDIFs in doc order, captures the specific unmatched tags
    // for the lint section.
    var unmatchedIfCount    = lint && lint.unmatchedIf    ? lint.unmatchedIf.length    : 0;
    var unmatchedEndifCount = lint && lint.unmatchedEndif ? lint.unmatchedEndif.length : 0;
    var balanced = (unmatchedIfCount === 0 && unmatchedEndifCount === 0);
    var hasIssue = !balanced || orphanCount > 0;
    var bg = hasIssue ? '#fef3c7' : '#dcfce7';
    var border = hasIssue ? '#fcd34d' : '#86efac';
    var fg = hasIssue ? '#92400e' : '#166534';
    var headerLabel = hasIssue ? '⚠ STRUCTURE ISSUES' : '✓ STRUCTURE OK';
    function _pill(label, n, danger, tip) {
      var pillBg = danger ? '#fee2e2' : '#fff';
      var pillFg = danger ? '#991b1b' : '#0f172a';
      var pillBorder = danger ? '#fca5a5' : '#cbd5e1';
      var tipAttr = tip ? ' title="' + _esc(tip) + '"' : '';
      return '<span' + tipAttr + ' style="display:inline-block;padding:2px 7px;font-size:10px;font-weight:700;background:' + pillBg + ';color:' + pillFg + ';border:1px solid ' + pillBorder + ';margin:2px 4px 2px 0;letter-spacing:0.04em;' + (tip ? 'cursor:help;' : '') + '">' +
        _esc(label) + ': <strong>' + n + '</strong>' +
        '</span>';
    }
    // Specific balance message based on the stack walk.
    var balanceLine;
    if (balanced) {
      balanceLine = '<div style="font-size:10px;color:' + fg + ';margin-top:4px;">IF/ENDIF balanced (' + ifN + ' / ' + endifN + ').</div>';
    } else {
      var bits = [];
      if (unmatchedIfCount)    bits.push('<strong>' + unmatchedIfCount    + '</strong> IF block' + (unmatchedIfCount === 1 ? '' : 's')    + ' missing ENDIF');
      if (unmatchedEndifCount) bits.push('<strong>' + unmatchedEndifCount + '</strong> extra ENDIF'   + (unmatchedEndifCount === 1 ? '' : 's') + ' with no matching IF');
      balanceLine = '<div style="font-size:10px;color:#991b1b;margin-top:4px;font-weight:700;">⚠ ' + bits.join(' · ') + ' — see Template Lint below for the exact tags.</div>';
    }
    var orphanLine = orphanCount > 0
      ? '<div style="font-size:10px;color:#991b1b;margin-top:2px;font-weight:700;">⚠ ' + orphanCount + ' IF/ELSEIF reference' + (orphanCount === 1 ? '' : 's') + ' with no matching DEF (see below).</div>'
      : '';
    return '<div style="background:' + bg + ';border:1px solid ' + border + ';padding:10px 12px;display:flex;flex-direction:column;gap:2px;">' +
      '<div style="font-size:10px;font-weight:900;letter-spacing:0.08em;color:' + fg + ';">' + headerLabel + '</div>' +
      '<div style="margin-top:4px;">' +
        _pill('IF', ifN, unmatchedIfCount > 0) +
        _pill('ELSEIF', elseifN, false) +
        _pill('ELSE', elseN, false) +
        _pill('ENDIF', endifN, unmatchedEndifCount > 0) +
        _pill('DEF', defCount, false) +
        (titleN ? _pill('TITLE', titleN, false) : '') +
        (keyN ? _pill('VAR', keyN, false, 'Bare {{NAME}} substitution placeholders — replaced by Build Draft Step 1 via _step1b_replaceKeys.') : '') +
      '</div>' +
      balanceLine +
      orphanLine +
    '</div>';
  }

  // Lint warnings — syntax-level bugs the engine silently swallows.
  // Each section only renders when it has items. Every flagged tag
  // shows a 🔎 button that jumps to its location in the doc via
  // _onFindInDoc.
  function _renderLintWarnings(lint) {
    function _row(raw, label) {
      return '<div style="display:flex;align-items:flex-start;gap:6px;font-size:10px;line-height:1.4;">' +
        (label ? '<span style="color:#7f1d1d;font-weight:700;flex-shrink:0;">' + _esc(label) + '</span>' : '') +
        '<code style="flex:1;font-family:monospace;color:#7f1d1d;background:rgba(255,255,255,0.5);padding:2px 6px;overflow:hidden;text-overflow:ellipsis;word-break:break-all;">' + _esc(raw) + '</code>' +
        '<button data-bdtt-jump="' + _esc(raw) + '" type="button" title="Find in doc" style="flex-shrink:0;padding:2px 6px;font-size:11px;background:#fff;border:1px solid #fca5a5;color:#991b1b;cursor:pointer;border-radius:0;">🔎</button>' +
      '</div>';
    }
    function _section(title, items, format) {
      if (!items || !items.length) return '';
      return '<div style="display:flex;flex-direction:column;gap:4px;">' +
        '<div style="font-size:10px;font-weight:800;color:#991b1b;letter-spacing:0.04em;">' + _esc(title) + ' (' + items.length + ')</div>' +
        items.map(format).join('') +
      '</div>';
    }
    return '<div style="background:#fef3c7;border:1px solid #fcd34d;padding:10px 12px;display:flex;flex-direction:column;gap:8px;">' +
      '<div style="font-size:10px;font-weight:900;letter-spacing:0.08em;color:#92400e;">⚠ TEMPLATE LINT</div>' +
      '<div style="font-size:10px;color:#92400e;line-height:1.45;">These tags compile but won\'t do what they look like they\'re doing. Build Draft will silently skip the branch / treat the tag as raw text.</div>' +
      _section("IF without matching ENDIF", lint.unmatchedIf, function (item) {
        return _row(item.raw, "missing ENDIF");
      }) +
      _section("ENDIF without matching IF", lint.unmatchedEndif, function (item) {
        return _row(item.raw, "extra");
      }) +
      _section("Single = instead of ==", lint.singleEquals, function (item) {
        return _row(item.raw, item.kind + " uses ' = '");
      }) +
      _section("Missing colon after keyword", lint.missingColon, function (item) {
        return _row(item.raw, "expects '" + item.expected + "'");
      }) +
      _section("Nested IF (not supported)", lint.nestedIf, function (item) {
        return _row(item.raw, "depth " + item.depth);
      }) +
      _section("DEF with no usable options", lint.emptyDef, function (item) {
        return _row(item.raw, item.name);
      }) +
    '</div>';
  }

  // Orphan list — IFs that reference a name with no DEF. Shows the
  // raw tag text so the user can find it in the doc. Doesn't try to
  // suggest fixes; just surfaces the bug.
  function _renderOrphans(orphans) {
    return '<div style="background:#fee2e2;border:1px solid #fca5a5;padding:10px 12px;display:flex;flex-direction:column;gap:6px;">' +
      '<div style="font-size:10px;font-weight:900;letter-spacing:0.08em;color:#991b1b;">⚠ ORPHAN IF REFERENCES</div>' +
      '<div style="font-size:10px;color:#7f1d1d;line-height:1.5;">These names are referenced by <code>IF</code> / <code>ELSEIF</code> but never <code>DEF</code>\'d — Step 1 won\'t render a dropdown for them and the branch will always be false:</div>' +
      orphans.map(function (o) {
        var refLines = o.refs.map(function (r) {
          return '<div style="display:flex;align-items:center;gap:6px;margin-top:2px;">' +
            '<code style="flex:1;font-family:monospace;font-size:10px;color:#7f1d1d;background:rgba(255,255,255,0.5);padding:2px 6px;overflow:hidden;text-overflow:ellipsis;word-break:break-all;">' + _esc(r.raw) + '</code>' +
            '<button data-bdtt-jump="' + _esc(r.raw) + '" type="button" title="Find in doc" style="flex-shrink:0;padding:2px 6px;font-size:11px;background:#fff;border:1px solid #fca5a5;color:#991b1b;cursor:pointer;border-radius:0;">🔎</button>' +
          '</div>';
        }).join("");
        return '<div style="display:flex;flex-direction:column;gap:2px;">' +
          '<div style="font-size:11px;font-weight:700;color:#991b1b;font-family:monospace;">' + _esc(o.name) +
            ' <span style="font-size:9px;color:#7f1d1d;font-weight:600;font-family:inherit;">(' + o.refs.length + ' reference' + (o.refs.length === 1 ? '' : 's') + ')</span>' +
          '</div>' +
          refLines +
        '</div>';
      }).join("") +
    '</div>';
  }
  // Per-card pill selection state. Maps def-name → {ifIdx, elseifIdx}.
  // Defaults: ifIdx = 0 (first choice), elseifIdx = 1 (second choice if
  // it exists, else 0). Persists across re-renders within the same
  // overlay session so user picks survive the "copy IF then click another
  // pill" loop. Cleared by _closeOverlay alongside _bdttScanReport.
  var _bdttCardSelections = {};
  function _getCardSel(d) {
    var sel = _bdttCardSelections[d.name];
    if (!sel) {
      sel = {
        ifIdx: 0,
        elseifIdx: d.options.length >= 2 ? 1 : 0,
      };
      _bdttCardSelections[d.name] = sel;
    }
    return sel;
  }

  function _renderDefCard(d) {
    var typeBadge = d.isText
      ? '<span style="font-size:9px;font-weight:800;letter-spacing:0.06em;padding:2px 6px;background:#fef3c7;color:#92400e;border:1px solid #fcd34d;text-transform:uppercase;">TEXT</span>'
      : '<span style="font-size:9px;font-weight:800;letter-spacing:0.06em;padding:2px 6px;background:#dbeafe;color:#1e40af;border:1px solid #93c5fd;text-transform:uppercase;">' +
          d.options.length + ' choice' + (d.options.length === 1 ? '' : 's') +
        '</span>';

    var defaultLine = d.defaultValue
      ? '<div style="font-size:9px;color:#64748b;letter-spacing:0.04em;">DEFAULT: <strong style="color:#0f172a;font-weight:600;">' + _esc(d.defaultValue) + '</strong></div>'
      : '';

    // Copy buttons. IF/ELSEIF disabled for text defs and when there
    // aren't enough options. The "Variable" copy always works.
    var canIf = !d.isText && d.options.length >= 1;
    var canElseIf = !d.isText && d.options.length >= 2;
    var btnStyle = "padding:5px 8px;font-size:10px;font-weight:700;letter-spacing:0.04em;border:1px solid #cbd5e1;background:#fff;color:#0f172a;cursor:pointer;border-radius:0;flex:1;text-transform:uppercase;";
    var btnDisabledStyle = "padding:5px 8px;font-size:10px;font-weight:700;letter-spacing:0.04em;border:1px solid #e2e8f0;background:#f8fafc;color:#cbd5e1;cursor:not-allowed;border-radius:0;flex:1;text-transform:uppercase;";

    var cardBorder = d.hasConflict ? "2px solid #f59e0b" : "1px solid #cbd5e1";
    var conflictBanner = d.hasConflict
      ? '<div style="font-size:10px;color:#92400e;background:#fef3c7;border:1px solid #fcd34d;padding:4px 8px;line-height:1.4;">' +
          '⚠ This NAME has <strong>' + d.variantCount + '</strong> different definitions in this document. The choices below are for this variant only.' +
        '</div>'
      : '';
    var countPill = d.count > 1
      ? '<span style="font-size:9px;font-weight:700;color:#475569;background:#f1f5f9;border:1px solid #cbd5e1;padding:1px 5px;letter-spacing:0.04em;">×' + d.count + '</span>'
      : '';
    var rawSample = '<div style="font-size:9px;color:#94a3b8;font-family:monospace;line-height:1.3;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;" title="' + _esc(d.normalized || d.raw) + '">' + _esc(d.normalized || d.raw) + '</div>';

    // Pill rows — text defs get a simple "free-text input" note;
    // choice defs get TWO rows of clickable pills (IF row + ELSEIF row
    // when there are ≥2 options). Selected pill is bold-bordered and
    // tinted; clicking another pill in the same row swaps selection.
    // The selected pill in each row is what the IF/ELSEIF copy button
    // uses.
    var sel = canIf ? _getCardSel(d) : null;
    function _pillRow(role) {
      var selectedIdx = sel ? (role === "if" ? sel.ifIdx : sel.elseifIdx) : -1;
      var roleLabel = role === "if"
        ? '<span style="display:inline-block;min-width:50px;font-size:9px;font-weight:900;letter-spacing:0.08em;color:#166534;background:#dcfce7;border:1px solid #86efac;padding:2px 6px;margin-right:6px;">IF =</span>'
        : '<span style="display:inline-block;min-width:50px;font-size:9px;font-weight:900;letter-spacing:0.08em;color:#92400e;background:#fef3c7;border:1px solid #fcd34d;padding:2px 6px;margin-right:6px;">ELSEIF =</span>';
      var pills = d.options.map(function (o, i) {
        var isSelected = (i === selectedIdx);
        var baseBg = role === "if" ? "#dcfce7" : "#fef3c7";
        var baseFg = role === "if" ? "#166534" : "#92400e";
        var baseBorder = role === "if" ? "#86efac" : "#fcd34d";
        var bg = isSelected ? baseBg : "#f8fafc";
        var fg = isSelected ? baseFg : "#475569";
        var border = isSelected ? "2px solid " + baseBorder : "1px solid #cbd5e1";
        var padding = isSelected ? "0 5px" : "1px 6px"; // compensate for thicker border
        var weight = isSelected ? 800 : 600;
        var checkmark = isSelected ? "✓ " : "";
        return '<button type="button" data-bdtt-pick="' + role + '" data-bdtt-name="' + _esc(d.name) + '" data-bdtt-idx="' + i + '" style="display:inline-block;background:' + bg + ';color:' + fg + ';border:' + border + ';padding:' + padding + ';margin:1px 4px 1px 0;font-weight:' + weight + ';font-size:10px;cursor:pointer;font-family:inherit;border-radius:0;letter-spacing:0.02em;">' + checkmark + _esc(o) + '</button>';
      }).join("");
      return '<div style="font-size:10px;line-height:1.7;display:flex;align-items:center;flex-wrap:wrap;">' + roleLabel + pills + '</div>';
    }

    var optionsHtml = d.isText
      ? '<div style="font-size:10px;color:#64748b;font-style:italic;">free-text input</div>'
      : '<div style="display:flex;flex-direction:column;gap:2px;">' +
          (canIf     ? _pillRow("if")     : '') +
          (canElseIf ? _pillRow("elseif") : '') +
        '</div>';

    // Tooltip text for IF/ELSEIF reflects the CURRENT selection.
    var ifChoice     = canIf     ? d.options[sel.ifIdx]     : '';
    var elseifChoice = canElseIf ? d.options[sel.elseifIdx] : '';

    // "Referenced by" row — shows every IF/ELSEIF that uses this DEF's
    // name, with click-to-jump per reference. Closes the loop between
    // DEFs and their conditionals. Hidden when there are no refs.
    var refsHtml = '';
    if (d.references && d.references.length) {
      var ifCount = d.references.filter(function (r) { return r.kind === "IF"; }).length;
      var eifCount = d.references.length - ifCount;
      var summary = [];
      if (ifCount) summary.push(ifCount + " IF");
      if (eifCount) summary.push(eifCount + " ELSEIF");
      refsHtml = '<div style="display:flex;flex-direction:column;gap:3px;">' +
        '<div style="font-size:9px;color:#475569;font-weight:700;letter-spacing:0.04em;">REFERENCED BY ' + summary.join(" · ") + '</div>' +
        '<div style="display:flex;flex-wrap:wrap;gap:3px;">' +
          d.references.map(function (ref) {
            var bg = ref.kind === "IF" ? "#dcfce7" : "#fef3c7";
            var fg = ref.kind === "IF" ? "#166534" : "#92400e";
            var bd = ref.kind === "IF" ? "#86efac" : "#fcd34d";
            var val = _extractCondValueForDisplay(ref.raw);
            return '<button data-bdtt-jump="' + _esc(ref.raw) + '" type="button" title="' + _esc(ref.raw) + '\nClick to find in doc" style="display:inline-flex;align-items:center;gap:3px;padding:2px 6px;font-size:10px;font-weight:600;cursor:pointer;font-family:inherit;border-radius:0;background:' + bg + ';color:' + fg + ';border:1px solid ' + bd + ';">' +
              ref.kind + ' <span style="font-family:monospace;">' + _esc(val) + '</span> 🔎' +
            '</button>';
          }).join('') +
        '</div>' +
      '</div>';
    }

    return '' +
      '<div data-bdtt-card="' + _esc(d.name) + '" style="border:' + cardBorder + ';background:#fff;padding:10px 12px;display:flex;flex-direction:column;gap:6px;">' +
        '<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap;">' +
          '<div style="display:flex;align-items:center;gap:6px;min-width:0;">' +
            '<code style="font-family:monospace;font-size:12px;font-weight:700;color:#1565c0;">' + _esc(d.name) + '</code>' +
            // Jump to this DEF tag itself.
            '<button data-bdtt-jump="' + _esc(d.normalized || d.raw) + '" type="button" title="Find this DEF in the doc" style="padding:0 5px;font-size:11px;background:#fff;border:1px solid #cbd5e1;color:#1565c0;cursor:pointer;border-radius:0;line-height:1.4;">🔎</button>' +
            countPill +
          '</div>' +
          typeBadge +
        '</div>' +
        conflictBanner +
        rawSample +
        defaultLine +
        refsHtml +
        optionsHtml +
        (d.warning
          ? '<div style="font-size:10px;color:#92400e;font-style:italic;line-height:1.4;">⚠️ ' + _esc(d.warning) + '</div>'
          : '') +
        '<div style="display:flex;gap:4px;margin-top:2px;">' +
          '<button data-bdtt-copy="var"     data-bdtt-name="' + _esc(d.name) + '" type="button" style="' + btnStyle + '" title="Copy {{' + _esc(d.name) + '}}">📋 Var</button>' +
          (canIf
            ? '<button data-bdtt-copy="if"     data-bdtt-name="' + _esc(d.name) + '" type="button" style="' + btnStyle + '" title="Copy {{IF: ' + _esc(d.name) + ' == ' + _esc(ifChoice) + '}}">📋 IF</button>'
            : '<button disabled type="button" style="' + btnDisabledStyle + '" title="IF requires at least one choice option">📋 IF</button>'
          ) +
          (canElseIf
            ? '<button data-bdtt-copy="elseif" data-bdtt-name="' + _esc(d.name) + '" type="button" style="' + btnStyle + '" title="Copy {{ELSEIF: ' + _esc(d.name) + ' == ' + _esc(elseifChoice) + '}}">📋 ELSEIF</button>'
            : '<button disabled type="button" style="' + btnDisabledStyle + '" title="ELSEIF requires at least two choice options">📋 ELSEIF</button>'
          ) +
        '</div>' +
        '<div data-bdtt-endif-hint style="display:none;font-size:10px;color:#92400e;font-style:italic;background:#fef3c7;border-left:3px solid #f59e0b;padding:5px 8px;margin-top:2px;">' +
          '💡 Don\'t forget to close with <code style="font-family:monospace;font-style:normal;font-weight:700;">{{ENDIF}}</code>.' +
        '</div>' +
      '</div>';
  }
  function _renderCopyText(d, kind) {
    // Build Draft's evalLogicCondition trims on every side of `==` and
    // around the `IF:` prefix, so this spacing is purely cosmetic.
    // Honor per-card selections so clicking a pill changes which value
    // gets baked into the IF/ELSEIF text.
    if (kind === "var") return "{{" + d.name + "}}";
    var sel = _getCardSel(d);
    if (kind === "if") {
      var iv = d.options[sel.ifIdx] || d.options[0] || "";
      return "{{IF: " + d.name + " == " + iv + "}}";
    }
    if (kind === "elseif") {
      var ev = d.options[sel.elseifIdx] || d.options[1] || "";
      return "{{ELSEIF: " + d.name + " == " + ev + "}}";
    }
    return null;
  }
  function _copyText(text, kind, name) {
    var label = kind === "var" ? "Variable"
              : kind === "if" ? "IF"
              : kind === "elseif" ? "ELSEIF"
              : kind === "def" ? "DEF"
              : "Tag";
    function _ok()  { _toast("✅ " + label + " for " + name + " copied", "ok"); }
    function _err() { _toast("Clipboard blocked — text shown in console as window.__bdtt_lastCopy.", "warn"); try { window.__bdtt_lastCopy = text; } catch (_) {} }
    if (navigator.clipboard && navigator.clipboard.writeText) {
      navigator.clipboard.writeText(text).then(_ok).catch(function () {
        // Fall back to the textarea/execCommand trick when the iframe
        // sandbox blocks the async API.
        var ta = document.createElement("textarea");
        ta.value = text;
        ta.style.cssText = "position:fixed;left:-9999px;opacity:0";
        document.body.appendChild(ta);
        ta.select();
        try {
          if (document.execCommand("copy")) _ok(); else _err();
        } catch (_) { _err(); }
        document.body.removeChild(ta);
      });
    } else {
      _err();
    }
  }

  // ─── Bottom toggle button — manual on/off ─────────────────────────
  // Always visible until user explicitly dismisses it. No DOM watchers,
  // no auto-hide on navigation. Visibility persists across reloads via
  // the kernel "config" store. To bring back after dismissing: click the
  // tile in the dashboard.
  //
  // Why manual: an auto-show/hide watcher needs MutationObserver on a
  // wide scope (the kernel replaces _eli3_dashboard_root on _goHome, so
  // anything bound to it goes stale) — which means firing on every
  // taskpane DOM mutation. Even rAF-coalesced, that's avoidable overhead
  // when the user is happy clicking a tile to restore.
  var TOGGLE_ID = "_bdtt_toggle_btn";
  var BTN_VIS_KEY = "bd_template_tester_btn_visible";

  function _loadBtnVisible() {
    // Default true — first install shows the button so user knows the
    // tool installed. Subsequent reads honor whatever the user picked.
    return eli.storage.get("config", BTN_VIS_KEY).then(function (row) {
      if (!row) return true;
      return row.value !== false;
    }).catch(function () { return true; });
  }
  function _saveBtnVisible(v) {
    return eli.storage.put("config", { key: BTN_VIS_KEY, value: !!v })
      .catch(function (e) {
        eli.log.event("tool", "bd_template_tester_btn_vis_put_failed", { msg: e && e.message });
      });
  }

  function _injectToggleButton() {
    if (document.getElementById(TOGGLE_ID)) return;
    var btn = document.createElement("button");
    btn.id = TOGGLE_ID;
    btn.type = "button";
    btn.title = "Open Template Tester (× to dismiss)";
    btn.style.cssText = [
      "position:fixed",
      "bottom:42px",
      "right:18px",
      // Below .eli-overlay (z-index 9999) so any dialog covers the
      // button visually.
      "z-index:9000",
      "padding:8px 14px 8px 14px",
      "font-size:11px",
      "font-weight:800",
      "letter-spacing:0.08em",
      "text-transform:uppercase",
      "color:#fff",
      "background:linear-gradient(135deg,#1e3a8a,#1565c0)",
      "border:1px solid #1e3a8a",
      "border-radius:0",
      "cursor:pointer",
      "box-shadow:0 4px 14px rgba(15,23,42,0.32)",
      "font-family:Inter,'Segoe UI',system-ui,sans-serif",
      "display:inline-flex",
      "align-items:center",
      "gap:10px",
    ].join(";") + ";";
    // Label span + dismiss × in one button — clicking the × hides the
    // button without opening the overlay.
    var label = document.createElement("span");
    label.textContent = "🧪 Test";
    var dismiss = document.createElement("span");
    dismiss.id = "_bdtt_dismiss";
    dismiss.textContent = "×";
    dismiss.title = "Hide button (click the dashboard tile to restore)";
    dismiss.style.cssText = [
      "display:inline-flex",
      "align-items:center",
      "justify-content:center",
      "width:16px",
      "height:16px",
      "font-size:16px",
      "font-weight:700",
      "line-height:1",
      "opacity:0.7",
      "border-left:1px solid rgba(255,255,255,0.25)",
      "padding-left:8px",
      "margin-left:-2px",
    ].join(";") + ";";
    btn.appendChild(label);
    btn.appendChild(dismiss);
    btn.onclick = function (e) {
      // Dismiss × → hide + persist. Don't open the overlay in this case.
      if (e.target && e.target.id === "_bdtt_dismiss") {
        e.stopPropagation();
        _hideToggleButton();
        _saveBtnVisible(false);
        _toast("Test button hidden. Click the Template Tester tile to bring it back.", "info");
        return;
      }
      // Main click → open/close overlay.
      if (document.getElementById("_bdtt_overlay")) _closeOverlay();
      else _openOverlay();
    };
    document.body.appendChild(btn);
    // If a Step 1 render is currently in flight (button was just
    // restored mid-render), re-apply the pulsing state immediately so
    // the user doesn't miss the indicator.
    if (_bdttStep1State === "rendering") _setToggleRenderingState(true);
  }
  function _hideToggleButton() {
    var btn = document.getElementById(TOGGLE_ID);
    if (btn && btn.parentNode) btn.parentNode.removeChild(btn);
  }

  // Inject a global @keyframes block ONCE so the test button can pulse
  // even when the overlay isn't mounted. Document-scoped, so it stays
  // valid across overlay open/close cycles.
  (function _injectPulseKeyframes() {
    if (document.getElementById("_bdtt_global_pulse")) return;
    var s = document.createElement("style");
    s.id = "_bdtt_global_pulse";
    s.textContent =
      "@keyframes _bdtt_pulse_btn {" +
        "0%,100% { background: linear-gradient(135deg, #f59e0b, #d97706); }" +
        "50%     { background: linear-gradient(135deg, #d97706, #b45309); }" +
      "}";
    document.head.appendChild(s);
  })();

  // Flip the floating test button into "rendering" state — amber
  // pulsing background, label swaps to "⏳ Rendering". Visible no
  // matter what panel the user is currently looking at (Step 1 form,
  // dashboard, another tool), as long as the button hasn't been
  // dismissed. Off again when Step 1 completes or fails.
  function _setToggleRenderingState(on) {
    var btn = document.getElementById(TOGGLE_ID);
    if (!btn) return;
    var label = btn.firstElementChild;
    if (on) {
      btn.style.background = "linear-gradient(135deg,#f59e0b,#d97706)";
      btn.style.borderColor = "#b45309";
      btn.style.animation = "_bdtt_pulse_btn 1.4s ease-in-out infinite";
      btn.title = "Build Draft is rendering — wait before clicking anything";
      if (label) label.textContent = "⏳ Rendering";
    } else {
      btn.style.background = "linear-gradient(135deg,#1e3a8a,#1565c0)";
      btn.style.borderColor = "#1e3a8a";
      btn.style.animation = "";
      btn.title = "Open Template Tester (× to dismiss)";
      if (label) label.textContent = "🧪 Test";
    }
  }

  // Initial paint — read persisted state once, inject if visible. No
  // ongoing watchers from here on.
  //
  // Auto-opens the overlay on every load (user explicitly asked: "it
  // should automatically show the dialog until you click test"). The
  // Test button toggles closed; no need to remember per-session "was
  // it dismissed", because dismissing the BUTTON is a separate persist
  // via the × on the button itself.
  _loadBtnVisible().then(function (visible) {
    if (!visible) return;
    _injectToggleButton();
    // Small delay so the kernel finishes its boot-time paint before
    // we layer a draggable overlay on top — avoids a flash where the
    // overlay appears mid-dashboard-mount.
    setTimeout(function () {
      if (document.getElementById(TOGGLE_ID) && !document.getElementById("_bdtt_overlay")) {
        _openOverlay();
      }
    }, 300);
  });

  // ─── Tile click ───────────────────────────────────────────────────
  // Single canonical "restore + open" path. Whether the button was
  // hidden or not, clicking the tile re-shows it AND opens the overlay.
  // This is the documented way to bring the button back after dismiss.
  eli.register({
    tile: {
      app_bd_template_tester: function () {
        _saveBtnVisible(true);
        _injectToggleButton();
        _openOverlay();
      },
    },
  });

  // ─── Build Draft Step 1 lifecycle listeners ───────────────────────
  // Three events from build_draft:
  //   • build_draft:step1_start  → substitution is starting, doc is
  //                                about to mutate. Show "rendering"
  //                                indicator.
  //   • build_draft:step1_done   → substitution finished, doc is
  //                                settled. Show "done + snapshot" CTA.
  //   • build_draft:step1_failed → chain aborted. Clear the indicator
  //                                so the spinner doesn't hang.
  // Each handler re-renders the overlay if it's currently showing the
  // Test tab so the banner updates immediately. If the overlay isn't
  // open, state still updates and shows on next open.
  function _onStep1Event(state, payload) {
    _bdttStep1State = state;
    _bdttLastStep1 = {
      ts: (payload && payload.ts) || Date.now(),
      fieldCount: (payload && payload.fieldCount) || 0,
      msg: payload && payload.msg,
    };
    if (document.getElementById("_bdtt_overlay") && _bdttTab === "test") {
      _renderOverlayBody();
    }
  }
  try {
    if (eli.bus && typeof eli.bus.on === "function") {
      eli.bus.on("build_draft:step1_start", function (p) {
        _onStep1Event("rendering", p);
        // Also flip the floating test button into "rendering" mode so
        // the user sees the indicator even when the overlay is
        // closed — which is the common case during Step 1 (build_draft
        // is the foreground panel, not the overlay).
        _setToggleRenderingState(true);
      });
      eli.bus.on("build_draft:step1_done", function () {
        _bdttStep1State = null;
        _bdttLastStep1 = null;
        _setToggleRenderingState(false);
        if (document.getElementById("_bdtt_overlay") && _bdttTab === "test") {
          _renderOverlayBody();
        }
      });
      eli.bus.on("build_draft:step1_failed", function (p) {
        _bdttStep1State = null;
        _bdttLastStep1 = null;
        _setToggleRenderingState(false);
        var msg = (p && p.msg) ? p.msg : "unknown";
        _toast("Step 1 failed: " + msg, "err");
        if (document.getElementById("_bdtt_overlay") && _bdttTab === "test") {
          _renderOverlayBody();
        }
      });
    }
  } catch (_step1SubErr) { /* tolerate — listener can rewire on next reload */ }

  eli.log.event("tool", "bd_template_tester_initialized", { email: userEmail });
}
